def compare_versions(a: str, b: str) -> int:
    def parse_version(version: str):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in version_without_build:
            core, prerelease = version_without_build.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = version_without_build
            prerelease_parts = None

        # Parse core version (MAJOR.MINOR.PATCH)
        major, minor, patch = map(int, core.split('.'))

        return (major, minor, patch), prerelease_parts

    def parse_prerelease_identifier(identifier: str):
        # Return (is_numeric, value) where numeric identifiers sort by int value,
        # non-numeric by string value
        if identifier.isdigit():
            return (0, int(identifier))  # 0 means numeric, sorts lower than non-numeric
        else:
            return (1, identifier)  # 1 means non-numeric

    core_a, prerelease_a = parse_version(a)
    core_b, prerelease_b = parse_version(b)

    # Compare core versions (MAJOR.MINOR.PATCH)
    if core_a != core_b:
        return -1 if core_a < core_b else 1

    # Core versions are equal, now compare pre-release
    # A version without pre-release has higher precedence than one with pre-release
    if prerelease_a is None and prerelease_b is None:
        return 0
    if prerelease_a is None:
        return 1  # a has no pre-release, so a > b
    if prerelease_b is None:
        return -1  # b has no pre-release, so a < b

    # Both have pre-release identifiers, compare them
    for i in range(max(len(prerelease_a), len(prerelease_b))):
        if i >= len(prerelease_a):
            # a has fewer identifiers, so a < b (fewer identifiers is lower precedence)
            return -1
        if i >= len(prerelease_b):
            # b has fewer identifiers, so a > b
            return 1

        id_a = parse_prerelease_identifier(prerelease_a[i])
        id_b = parse_prerelease_identifier(prerelease_b[i])

        if id_a != id_b:
            return -1 if id_a < id_b else 1

    return 0
